CREATE TABLE laporan (order_id TEXT PRIMARY KEY, hari TEXT NOT NULL, jumlah INTEGER NOT NULL);
CREATE TABLE jurnal_topup (order_id TEXT PRIMARY KEY, hari TEXT NOT NULL, jumlah INTEGER NOT NULL);
CREATE TABLE insiden_rekon (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL, jenis TEXT NOT NULL CHECK (jenis IN ('tidak_di_ledger', 'tidak_di_gateway', 'jumlah_beda')), selisih INTEGER NOT NULL, UNIQUE (order_id, jenis));
